import hashlib,json,re,sys
from pathlib import Path
from pypdf import PdfReader
from pypdf.generic import IndirectObject, StreamObject
sys.stdout.reconfigure(encoding='utf-8')
p=Path(r'D:\tools\charter.pdf')
r=PdfReader(str(p))
terms=['velvet','village','archive','archival','json','jason','footnote','annotation','hidden','metadata','source','golden wings','gold wingers']
result={
 'sha256':hashlib.sha256(p.read_bytes()).hexdigest().upper(),
 'size':p.stat().st_size,
 'pages':len(r.pages),
 'encrypted':r.is_encrypted,
 'metadata':{str(k):str(v) for k,v in (r.metadata or {}).items()},
 'root_keys':[str(k) for k in r.trailer['/Root'].keys()],
 'trailer_keys':[str(k) for k in r.trailer.keys()],
 'attachments':{},
 'named_destinations':list(r.named_destinations.keys()),
 'outline':str(r.outline),
 'page_annotations':[],
 'page_keys':[],
 'matches':[],
 'objects_scanned':0,
 'stream_objects':0,
 }
try:
    result['attachments']={k:[len(x) for x in v] for k,v in r.attachments.items()}
except Exception as e:
    result['attachments_error']=f'{type(e).__name__}: {e}'
try:
    xmp=r.xmp_metadata
    result['xmp_present']=xmp is not None
    if xmp is not None:
        attrs=['dc_title','dc_description','dc_subject','dc_creator','pdf_keywords','pdf_producer','xmp_creator_tool','custom_properties']
        result['xmp']={a:str(getattr(xmp,a,None)) for a in attrs}
except Exception as e:
    result['xmp_error']=f'{type(e).__name__}: {e}'
for i,page in enumerate(r.pages,1):
    result['page_keys'].append({'page':i,'keys':[str(k) for k in page.keys()]})
    ann=page.get('/Annots')
    if ann:
        result['page_annotations'].append({'page':i,'annotations':str(ann)})
seen=set()
def inspect_obj(objnum,generation,obj):
    result['objects_scanned']+=1
    pieces=[]
    try: pieces.append(str(obj))
    except: pass
    if isinstance(obj,StreamObject):
        result['stream_objects']+=1
        try:
            data=obj.get_data()
            pieces.append(data.decode('utf-8','ignore'))
            pieces.append(data.decode('latin-1','ignore'))
        except Exception as e:
            pieces.append(f'[stream decode error {e}]')
    text='\n'.join(pieces)
    for term in terms:
        for m in re.finditer(re.escape(term),text,re.I):
            lo=max(0,m.start()-100); hi=min(len(text),m.end()+180)
            result['matches'].append({'object':f'{objnum} {generation} R','term':term,'context':text[lo:hi].replace('\x00',' ')})
for generation,ids in r.xref.items():
    for objnum in ids:
        key=(objnum,generation)
        if key in seen: continue
        seen.add(key)
        try: obj=r.get_object(IndirectObject(objnum,generation,r)); inspect_obj(objnum,generation,obj)
        except Exception as e: result.setdefault('object_errors',[]).append({'object':f'{objnum} {generation} R','error':str(e)})
print(json.dumps(result,ensure_ascii=False,indent=2))
